// Точный перебор числа расстановок флота (без касания запрещено? нет, касание разрешено)
function shipPlacements(W,H,len){
  const out=[];
  for(let r=0;r<H;r++)for(let c=0;c+len<=W;c++){const m=[];for(let i=0;i<len;i++)m.push(r*W+c+i);out.push(m);}
  if(len>1)for(let c=0;c<W;c++)for(let r=0;r+len<=H;r++){const m=[];for(let i=0;i<len;i++)m.push((r+i)*W+c);out.push(m);}
  return out;
}
function countFleet(W,H,fleet,limit){
  // fleet: array of lengths, identical lengths -> делим на факториалы в конце
  const lists=fleet.map(l=>shipPlacements(W,H,l));
  let n=0; const occ=new Uint8Array(W*H);
  function rec(i){
    if(n>limit) return;
    if(i===lists.length){n++;return;}
    // для одинаковых длин требуем возрастающий индекс размещения
    const same = i>0 && fleet[i]===fleet[i-1];
    for(let k=0;k<lists[i].length;k++){
      if(same && k<=rec.last[i-1]) continue;
      const p=lists[i][k]; let ok=true;
      for(const cel of p) if(occ[cel]){ok=false;break;}
      if(!ok) continue;
      for(const cel of p) occ[cel]=1;
      rec.last[i]=k; rec(i+1);
      for(const cel of p) occ[cel]=0;
      if(n>limit) return;
    }
  }
  rec.last=new Array(fleet.length).fill(-1);
  rec(0); return n;
}
