// Оценка числа расстановок методом последовательной выборки (SIS): несмещённая.
function estimate(W,H,fleet,N=200000){
  const lists=fleet.map(l=>shipPlacements(W,H,l));
  let dupDiv=1,run=1;
  for(let i=1;i<fleet.length;i++){ if(fleet[i]===fleet[i-1]){run++;dupDiv*=run;} else run=1; }
  let sum=0;
  const occ=new Uint8Array(W*H);
  for(let t=0;t<N;t++){
    occ.fill(0); let w=1; let ok=true;
    for(let i=0;i<lists.length;i++){
      const cand=[];
      for(const p of lists[i]){let f=true;for(const c of p) if(occ[c]){f=false;break;} if(f)cand.push(p);}
      if(cand.length===0){ok=false;break;}
      w*=cand.length;
      const p=cand[(Math.random()*cand.length)|0];
      for(const c of p) occ[c]=1;
    }
    if(ok) sum+=w;
  }
  return (sum/N)/dupDiv;
}
